test('overdueInvoices sorts by daysOverdue descending', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-09-15',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-003',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-2026-0002');
  assert.equal(result[0].daysOverdue, 36);
  assert.equal(result[1].number, 'INV-2026-0001');
  assert.equal(result[1].daysOverdue, 22);
  assert.equal(result[2].number, 'INV-2026-0003');
  assert.equal(result[2].daysOverdue, 6);
});

test('overdueInvoices handles empty invoice list', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.equal(result.length, 0);
  assert.deepEqual(result, []);
});

test('overdueInvoices handles mixed statuses', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      status: 'partially_paid',
      dueDate: '2026-09-15',
      lines: [{ qty: 1, unitPrice: 50000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 20000, date: '2026-10-01' }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-003',
      status: 'draft',
      dueDate: '2026-08-15',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0004',
      customerId: 'C-004',
      status: 'paid',
      dueDate: '2026-08-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 10000, date: '2026-10-01' }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[1].number, 'INV-2026-0002');
});

test('overdueInvoices calculates due for partially paid with multiple payments', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'partially_paid',
      dueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 100000, discountPercent: 0, vatRate: 0 }],
      payments: [
        { amount: 30000, date: '2026-09-05' },
        { amount: 40000, date: '2026-10-01' },
      ],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 30000);
});

test('overdueInvoices with VAT on lines', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  const expectedTotal = 10000 + Math.round(10000 * 21 / 100);
  assert.equal(result[0].due, expectedTotal);
});

test('overdueInvoices with discount on lines', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 20, vatRate: 0 }],
    },
